import 'package:flutter/cupertino.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../../common/Search/presentation/pages/search_screen.dart';import '../../../common/User/presentation/pages/user_screen.dart';import '../../Explore/presentation/pages/explore_srceen.dart';import '../../Home/presentation/pages/home_page.dart';class MainCubit extends Cubit<int> {  MainCubit() : super(0);  void changeIndex(int index) {    emit(index);  }  Widget listScreens() {    Widget widget(int index) => Center(          child: Text(index.toString()),        );    switch (state) {      case 0:        return HomePage();      case 1:        return ExploreScreen();      case 2:        return widget(444);      case 3:        return SearchScreen();      case 4:        return UserScreen();      default:        return widget(404);    }  }}